descriptor.controllerScript:
let imageZones = [], alarms = [], markers = [], intervalId;

self.onInit = function() {
    self.ctx.$scope.mapWidget.onInit();

    intervalId = setInterval(() => {
        drawAlarm(self.ctx.$scope.mapWidget.map.currentTime, alarms);
    }, 1000);
};

self.onDataUpdated = function(){
    self.ctx.data[0].data.forEach(x=>{
        if(x[1] && JSON.parse(x[1])){
            let alarm = JSON.parse(x[1]);
            alarms.push({
                ts: x[0],
                message: alarm.type,
                latitude: alarm.latitude,
                longitude: alarm.longitude,
                isDrawed: false
            });
        }
    });
};

function drawAlarm(time, alarms){
    alarms.forEach((alarm, index)=>{
        if(alarm.ts < time){
            if(!alarm.isDrawed){
                drawMarker(alarm.latitude, alarm.longitude, alarm.message, self.ctx.mapInstance.map);
                alarm.isDrawed = true;
            }
        } else {
            alarm.isDrawed = false;
            findAndDeleteMarker(alarm.latitude, alarm.longitude);
        }
    });
}

function drawMarker(lat, lng, popupText, map){
    const customIcon = L.icon({
        iconUrl: icon, 
        iconSize: [26, 26], 
        iconAnchor: [13, 26], 
        popupAnchor: [0, -26]
    });

    const marker = L.marker([lat, lng], { icon: customIcon }).addTo(map);

    markers.push(marker);
}

function findAndDeleteMarker(lat, lng) {
    const targetLatLng = L.latLng(lat, lng);

    for (let i = 0; i < markers.length; i++) {
        if (markers[i].getLatLng().equals(targetLatLng)) {
            markers[i].removeFrom(self.ctx.mapInstance.map);
            markers.splice(i, 1);
        }
    }

    return false;
}

self.onLatestDataUpdated = function(){
    self.ctx.latestData.forEach(x=>{
        if(!imageZones.some(zone=>zone.id.id == x.datasource.entityId)){
                imageZones.push({
                    id: x.datasource.entity.id,
                    name: x.datasource.name,
                    isDrawed: false
                });
        }
    });

    self.ctx.latestData.forEach(x=>{
        imageZones.forEach(y=>{
            if(x.datasource.entityId == y.id.id){
                y[x.dataKey.name] = x.data[0][1];
            }
        });
    });

    imageZones.forEach(zone => {
        if(!zone.isDrawed){
            var point1 = L.latLng(JSON.parse(zone.pointA)[0], JSON.parse(zone.pointA)[1]),
        	    point2 = L.latLng(JSON.parse(zone.pointB)[0], JSON.parse(zone.pointB)[1]), 
        	    point3 = L.latLng(JSON.parse(zone.pointC)[0], JSON.parse(zone.pointC)[1]);

            var overlay = L.imageOverlay.rotated(zone.image, point1, point2, point3, {
        		opacity: 0.8,
        		interactive: true
        	});

        	setTimeout(() => {
        	    if (self.ctx.$scope.mapWidget) {
        	        self.ctx.$scope.mapWidget.map.map.addLayer(overlay);
        	    }
        	}, 0);

        	zone.isDrawed = true;
        }
    });
};

self.typeParameters = function() {
    return {
        trip: true,
        hideDataTab: false,
        dataKeysOptional: true,
        hideDataSettings: true,
        hasAdditionalLatestDataKeys: true,
        previewWidth: '80%',
        embedTitlePanel: true,
        embedActionsPanel: true,
        datasourcesOptional: true,
        additionalWidgetActionTypes: ['placeMapItem']
    };
};

let icon = `data:image/png;base64,`;

L.ImageOverlay.Rotated = L.ImageOverlay.extend({
	initialize: function (image, topleft, topright, bottomleft, options) {
		if (typeof(image) === 'string') {
			this._url = image;
		} else {
			this._rawImage = image;
		}

		this._topLeft    = L.latLng(topleft);
		this._topRight   = L.latLng(topright);
		this._bottomLeft = L.latLng(bottomleft);

		L.setOptions(this, options);
	},

	onAdd: function (map) {
		if (!this._image) {
			this._initImage();

			if (this.options.opacity < 1) {
				this._updateOpacity();
			}
		}

		if (this.options.interactive) {
			L.DomUtil.addClass(this._rawImage, 'leaflet-interactive');
			this.addInteractiveTarget(this._rawImage);
		}

		map.on('zoomend resetview', this._reset, this);

		this.getPane().appendChild(this._image);
		this._reset();
	},

    onRemove: function(map) {
        map.off('zoomend resetview', this._reset, this);
        L.ImageOverlay.prototype.onRemove.call(this, map);
    },

	_initImage: function () {
		var img = this._rawImage;
		if (this._url) {
			img = L.DomUtil.create('img');
			img.style.display = 'none';

			if (this.options.crossOrigin) {
				img.crossOrigin = '';
			}

			img.src = this._url;
			this._rawImage = img;
		}
		L.DomUtil.addClass(img, 'leaflet-image-layer');

		var div = this._image = L.DomUtil.create('div',
				'leaflet-image-layer ' + (this._zoomAnimated ? 'leaflet-zoom-animated' : ''));

		this._updateZIndex(); 

		div.appendChild(img);

		div.onselectstart = L.Util.falseFn;
		div.onmousemove = L.Util.falseFn;

		img.onload = function(){
			this._reset();
			img.style.display = 'block';
			this.fire('load');
		}.bind(this);

		img.alt = this.options.alt;
	},

	_reset: function () {
		var div = this._image;

		if (!this._map) {
			return;
		}

		var pxTopLeft    = this._map.latLngToLayerPoint(this._topLeft);
		var pxTopRight   = this._map.latLngToLayerPoint(this._topRight);
		var pxBottomLeft = this._map.latLngToLayerPoint(this._bottomLeft);
		var pxBottomRight = pxTopRight.subtract(pxTopLeft).add(pxBottomLeft);

		var pxBounds = L.bounds([pxTopLeft, pxTopRight, pxBottomLeft, pxBottomRight]);
		var size = pxBounds.getSize();
		var pxTopLeftInDiv = pxTopLeft.subtract(pxBounds.min);

		this._bounds = L.latLngBounds( this._map.layerPointToLatLng(pxBounds.min),
		                               this._map.layerPointToLatLng(pxBounds.max) );

		L.DomUtil.setPosition(div, pxBounds.min);

		div.style.width  = size.x + 'px';
		div.style.height = size.y + 'px';

		var imgW = this._rawImage.width;
		var imgH = this._rawImage.height;
		if (!imgW || !imgH) {
			return;
		}

		var vectorX = pxTopRight.subtract(pxTopLeft);
		var vectorY = pxBottomLeft.subtract(pxTopLeft);

		this._rawImage.style.transformOrigin = '0 0';
		this._rawImage.style.transform = "matrix(" +
			(vectorX.x/imgW) + ', ' + (vectorX.y/imgW) + ', ' +
			(vectorY.x/imgH) + ', ' + (vectorY.y/imgH) + ', ' +
			pxTopLeftInDiv.x + ', ' + pxTopLeftInDiv.y + ')';
	},

	reposition: function(topleft, topright, bottomleft) {
		this._topLeft    = L.latLng(topleft);
		this._topRight   = L.latLng(topright);
		this._bottomLeft = L.latLng(bottomleft);
		this._reset();
	},

	setUrl: function (url) {
		this._url = url;

		if (this._rawImage) {
			this._rawImage.src = url;
		}
		return this;
	}
});


L.imageOverlay.rotated = function(imgSrc, topleft, topright, bottomleft, options) {
	return new L.ImageOverlay.Rotated(imgSrc, topleft, topright, bottomleft, options);
};
